-- Exported from project swiftborder (cam2701.v_congestion_index_10min) on 2026-09-26 via INFORMATION_SCHEMA.TABLES.

CREATE OR REPLACE VIEW `swiftborder.cam2701.v_congestion_index_10min`
AS WITH det AS (SELECT DATETIME(date, time) AS frame_sgt, filename, direction, base_class, is_night, brightness FROM `swiftborder.cam2701.Cam2701` WHERE direction IN ('to_JB', 'to_Woodlands') AND base_class IN ('car', 'motorcycle', 'bus', 'truck')), per_frame AS (SELECT filename, frame_sgt, CASE direction WHEN 'to_Woodlands' THEN 'MY_TO_SG' WHEN 'to_JB' THEN 'SG_TO_MY' END AS direction, COUNT(*) AS n_vehicles, COUNTIF(base_class = 'car') AS n_car, COUNTIF(base_class = 'motorcycle') AS n_motorcycle, COUNTIF(base_class = 'bus') AS n_bus, COUNTIF(base_class = 'truck') AS n_truck, MAX(is_night) AS is_night, AVG(brightness) AS brightness FROM det GROUP BY 1,2,3) SELECT direction, TIMESTAMP(DATETIME_TRUNC(frame_sgt, MINUTE) - INTERVAL MOD(EXTRACT(MINUTE FROM frame_sgt), 10) MINUTE, 'Asia/Singapore') AS bin_ts, AVG(n_vehicles) AS vis_count, AVG(n_car) AS vis_car, AVG(n_motorcycle) AS vis_motorcycle, AVG(n_bus) AS vis_bus, AVG(n_truck) AS vis_truck, MAX(is_night) AS vis_is_night, AVG(brightness) AS vis_brightness, COUNT(*) AS vis_frames FROM per_frame GROUP BY 1,2;
